const MOD = 1000000007;
const MAXN = 1000;

const fact = new Array(MAXN + 1);
const invFact = new Array(MAXN + 1);

function modPow(a, e) {
    let res = 1;
    while (e > 0) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

function precompute() {
    fact[0] = 1;
    for (let i = 1; i <= MAXN; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    invFact[MAXN] = modPow(fact[MAXN], MOD - 2);
    for (let i = MAXN; i >= 1; i--) {
        invFact[i - 1] = (invFact[i] * i) % MOD;
    }
}

function solve() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    if (input.length === 0) return;
    const n = parseInt(input[0]);
    const x = parseInt(input[1]);
    const pos = parseInt(input[2]);

    let left = 0;
    let right = n;
    let cntLess = 0;
    let cntGreater = 0;

    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (mid === pos) {
            left = mid + 1;
        } else if (mid < pos) {
            cntLess++;
            left = mid + 1;
        } else {
            cntGreater++;
            right = mid;
        }
    }

    const availableLess = x - 1;
    const availableGreater = n - x;

    if (cntLess > availableLess || cntGreater > availableGreater) {
        console.log(0);
        return;
    }

    let ans = 1;
    // P(availableLess, cntLess)
    ans = (ans * fact[availableLess]) % MOD;
    ans = (ans * invFact[availableLess - cntLess]) % MOD;

    // P(availableGreater, cntGreater)
    ans = (ans * fact[availableGreater]) % MOD;
    ans = (ans * invFact[availableGreater - cntGreater]) % MOD;

    // Remaining positions
    const remaining = n - 1 - cntLess - cntGreater;
    ans = (ans * fact[remaining]) % MOD;

    console.log(ans);
}

precompute();
solve();
